import{z as B,x as l,o as r,c as d,q as n,j as i,D as E,d as t,s as o,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"验证与测试平台","description":"","frontmatter":{"title":"验证与测试平台","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/verification-testbench.md","filePath":"cs/verification-testbench.md","lastUpdated":1791063341000}'),p={name:"cs/verification-testbench.md"};function c(D,a,T,h,m,F){const s=l("Mermaid");return r(),d("div",null,[a[2]||(a[2]=n('<h1 id="验证与测试平台" tabindex="-1">验证与测试平台 <a class="header-anchor" href="#验证与测试平台" aria-label="Permalink to &quot;验证与测试平台&quot;">​</a></h1><div class="epigraph"><p>综合与 STA 不读规范：测试平台驱动时钟与向量，对照参考模型；覆盖率只说明跑过哪些角落，不能证明没有漏网。</p><footer>—— 据 Bergeron, Writing Testbenches；IEEE Std 1800（SystemVerilog）；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p><a href="/cs/moore-law-economics">上一课</a>把验证列入 NRE。<a href="/cs/synthesis-netlist">综合</a>只翻译 RTL。<a href="/cs/sta">STA</a> 只查时序。缺口是<strong>功能验证</strong>：用测试平台（testbench）给算术单元与 FIFO 施加激励，检查饱和、空满、754 标志是否符合规范。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RTL 并行、有 CDC、有复位释放窗口。软件式 <code>main</code> 测不完。测试平台：不可综合的 <code>initial</code>/<code>fork</code>、时钟生成、断言、对照黄金模型（C 参考或更高级别）。缺口不是再写非阻塞规则，而是<strong>分层</strong>：单元测 FMA，系统测指令流。覆盖：代码覆盖、功能覆盖（是否碰到 NaN、几乎满）。覆盖 100% 仍可能漏未建模的场景。</p><p>随机约束（CRV）在 SV 里生成合法向量，适合除法边界与 FIFO 交织。本课钉结构，不背 UVM 类树。</p><h3 id="测试平台不是综合后的第二种芯片" tabindex="-1">测试平台不是综合后的第二种芯片 <a class="header-anchor" href="#测试平台不是综合后的第二种芯片" aria-label="Permalink to &quot;测试平台不是综合后的第二种芯片&quot;">​</a></h3><p>TB 不进网表。把 <code>$display</code> 留在可综合模块里会被忽略或报错。门级仿真用网表+SDF 延迟，仍由同一类 TB 驱动，用来抓时序与 X 传播，不替代 STA。</p><p><span class="marginnote">Bergeron 的 testbench 书是经典。IEEE 1800 含断言与功能覆盖。Harris 用简单 TB 教仿真。Cummings 的 FIFO 论文含测试建议。</span></p><p><span class="marginnote">术语翻译：计分板（scoreboard）就是用「把 DUT 输出与黄金模型的期望结果逐条对账」的手段来做「自动发现输出错误」的事——它像银行流水核对，两边对不上就报错，不需要人眼盯波形。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>DUT 例化。驱动：合法复位释放后再发事务。监测：分数、旗标、FIFO 数据序。计分板存入序，核对出序。CDC：用两时钟，故意偏斜。断言：不满时写、754 invalid 当 sNaN。回归：每次 RTL 改动重跑。</p>',12)),(r(),i(A,null,{default:E(()=>[o(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20REF%5B%22%E5%8F%82%E8%80%83%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20SB%5B%22%E8%AE%A1%E5%88%86%E6%9D%BF%22%5D%0A%20%20DRV%5B%22%E9%A9%B1%E5%8A%A8%E6%BF%80%E5%8A%B1%22%5D%20--%3E%20DUT%5B%22RTL%20%2F%20%E7%BD%91%E8%A1%A8%22%5D%0A%20%20DUT%20--%3E%20SB%0A%20%20COV%5B%22%E8%A6%86%E7%9B%96%E7%82%B9%22%5D%20--%3E%20GAP%5B%22%E6%9C%AA%E8%A6%86%E7%9B%96%E7%9A%84%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20SB%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%AD%89%E4%BB%B7%E6%A3%80%E6%9F%A5%E8%A1%A5%E4%BB%BF%E7%9C%9F%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<p>HLS 的 C 仿真是更上层的 TB，仍要 RTL 协同仿真，因调度可能改延迟接口。</p><p><span class="marginnote">数字实例：一个 32 位乘法器有 \\(2^{64}\\) 种输入组合，按每秒仿真十亿次也要五百多年跑完——这就是为什么靠定向向量测不完，必须用受约束随机（CRV）把激励集中在「除零、NaN、几乎满」这些真正出过事的边界附近。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下一课形式等价：在综合前后比逻辑锥，不靠向量。DFT 引入测试模式，TB 还要测扫描。本课的仿真是动态验证。功耗向量也可从 TB 来，但功能正确优先。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 UVM 的 factory 细节，不把形式属性语言的全部时序算子列完（下一课只谈等价）。不把模糊测试当数字前端的唯一方法。不进入软件用户态测试框架。</p><p>后课默认：功能靠 TB+覆盖+断言；通过不等于证明；综合后还要等价检查。</p>',7)),(r(),i(A,null,{default:E(()=>[o(s,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20PLAN%5B%22%E8%A6%86%E7%9B%96%E8%AE%A1%E5%88%92%3A%20%E5%9C%BA%E6%99%AF%E6%B8%85%E5%8D%95%22%5D%20--%3E%20GEN%5B%22%E5%8F%97%E7%BA%A6%E6%9D%9F%E9%9A%8F%E6%9C%BA%E7%94%9F%E6%88%90%E6%BF%80%E5%8A%B1%22%5D%0A%20%20GEN%20--%3E%20DRV%5B%22%E9%A9%B1%E5%8A%A8%20DUT%22%5D%0A%20%20DRV%20--%3E%20MON%5B%22%E7%9B%91%E6%B5%8B%E5%99%A8%E9%87%87%E6%A0%B7%E8%BE%93%E5%87%BA%22%5D%0A%20%20MON%20--%3E%20SB%5B%22%E8%AE%A1%E5%88%86%E6%9D%BF%E5%AF%B9%E7%85%A7%E5%8F%82%E8%80%83%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20MON%20--%3E%20COV%5B%22%E5%8A%9F%E8%83%BD%E8%A6%86%E7%9B%96%3A%20NaN%2C%20%E5%87%A0%E4%B9%8E%E6%BB%A1%2C%20%E5%A4%8D%E4%BD%8D%E7%AA%97%E5%8F%A3%22%5D%0A%20%20COV%20--%20%22%E6%9C%89%E6%9C%AA%E8%A6%86%E7%9B%96%E8%A7%92%E8%90%BD%22%20--%3E%20PLAN%0A%20%20COV%20--%20%22%E8%A6%86%E7%9B%96%E6%94%B6%E6%95%9B%22%20--%3E%20PASS%5B%22%E5%9B%9E%E5%BD%92%E9%80%9A%E8%BF%87%2C%20%E4%BD%86%E9%9D%9E%E8%AF%81%E6%98%8E%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易把「覆盖率 100%」读成「芯片没 bug」，实际上覆盖只回答「清单上的角落跑过没有」——清单外未建模的场景（如某个从未设想的 CDC 组合）一条覆盖都不会计入，仿真通过依然不构成证明。")],-1)),a[5]||(a[5]=e("h2",{id:"小结",tabindex:"-1"},[t("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[6]||(a[6]=e("ul",null,[e("li",null,"STA 与综合不验证规范；TB 驱动并对照参考模型。"),e("li",null,"覆盖指导缺口，不是证明。"),e("li",null,"TB 不可综合；门级仿真另加延迟。"),e("li",null,"出处：Bergeron；IEEE 1800；Harris and Harris。")],-1))])}const f=B(p,[["render",c]]);export{C as __pageData,f as default};
